#!/usr/bin/env node
import { copyFile, mkdir, readdir, stat } from 'node:fs/promises';
import path from 'node:path';
import process from 'node:process';
import { fileURLToPath } from 'node:url';

if (process.argv[2] === 'scaffold') {
  const { run } = await import('./scaffold.mjs');
  try {
    await run(process.argv.slice(3));
  } catch (error) {
    console.error(`shipyard scaffold: ${error.message}`);
    process.exit(1);
  }
  process.exit(0);
}

const packageRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const targetRoot = path.resolve(process.env.INIT_CWD || process.cwd());
const copyTargets = [
  { source: 'skills', target: 'skills' },
  { source: 'prompt-library', target: 'prompt-library' },
  { source: 'setup', target: '.' },
];

async function exists(filePath) {
  return Boolean(await stat(filePath).catch(() => null));
}

async function copyMissingDirectory(sourceDir, targetDir) {
  await mkdir(targetDir, { recursive: true });

  const entries = await readdir(sourceDir, { withFileTypes: true });
  let copied = 0;
  let skipped = 0;

  for (const entry of entries) {
    const sourcePath = path.join(sourceDir, entry.name);
    const targetPath = path.join(targetDir, entry.name);

    if (entry.isDirectory()) {
      const result = await copyMissingDirectory(sourcePath, targetPath);
      copied += result.copied;
      skipped += result.skipped;
      continue;
    }

    if (!entry.isFile()) {
      continue;
    }

    if (await exists(targetPath)) {
      skipped += 1;
      continue;
    }

    await mkdir(path.dirname(targetPath), { recursive: true });
    await copyFile(sourcePath, targetPath);
    copied += 1;
  }

  return { copied, skipped };
}

if (targetRoot === packageRoot || targetRoot.includes(`${path.sep}node_modules${path.sep}`)) {
  process.exit(0);
}

let copied = 0;
let skipped = 0;

for (const copyTarget of copyTargets) {
  const sourceDir = path.join(packageRoot, copyTarget.source);
  const targetDir = path.join(targetRoot, copyTarget.target);

  if (!(await exists(sourceDir))) {
    continue;
  }

  const result = await copyMissingDirectory(sourceDir, targetDir);
  copied += result.copied;
  skipped += result.skipped;
}

console.log(`@symbtech/shipyard setup copied ${copied} files to ${targetRoot}.`);
if (skipped > 0) {
  console.log(`@symbtech/shipyard setup skipped ${skipped} existing files.`);
}
